class Spell {
  constructor(name) {
    this.name = name;
  }

  cast() {
    return `${this.name} is cast with a generic effect.`;
  }
}

class FireballSpell extends Spell {
  constructor() {
    super("Fireball");
  }

  cast() {
    return `The ${this.name} spell erupts in a burst of flames!`;
  }
}

class HealSpell extends Spell {
  constructor() {
    super("Heal");
  }

  cast() {
    return `The ${this.name} spell mends wounds and restores vitality!`;
  }
}

class ShieldSpell extends Spell {
  constructor() {
    super("Shield");
  }

  cast() {
    return `The ${this.name} spell forms a shimmering protective barrier!`;
  }
}

